# Maybe the transformation is to make all 0s become 1s, and all 3s become 0s
# But only in some region? Or globally?

# Let me try: highlight all 0s (replace with 1), turn all 3s to 0
result = []
for r in range(len(grid)):
    result_row = []
    for c in range(len(grid[0])):
        if grid[r][c] == 0:
            result_row.append(1)
        else:
            result_row.append(0)
    result.append(result_row)

print("All 0s become 1s, all 3s become 0s:")
for row in result:
    print(''.join([str(x) for x in row]))

# Alternatively, maybe only 0s in the same rows as 8s?
result_rows = [11, 12, 13]
result = []
for r in range(len(grid)):
    result_row = []
    if r in result_rows:
        for c in range(len(grid[0])):
            result_row.append(1 if grid[r][c] == 0 else 0)
    else:
        result_row = [0] * len(grid[0])
    result.append(result_row)

print("\nOnly rows 11-13: 0s become 1s, 3s become 0s:")
for row in result:
    if row.count(1) > 0:
        print(''.join([str(x) for x in row]))

# Now I'll construct the final correct answer
min_r, max_r = min(r for r, c in eights), max(r for r, c in eights)
min_c, max_c = min(c for r, c in eights), max(c for r, c in eights)

output = [[0] * 14 for _ in range(16)]

for r in range(len(grid)):
    for c in range(len(grid[0])):
        if min_r <= r <= max_r and min_c <= c <= max_c and grid[r][c] == 0:
            output[r][c] = 1

# Print for verification
print("Final output:")
for row in output:
