# Let me try: full 16x14 grid, with 0 everywhere except rows 11-13
# In rows 11-13, 8->1 and 3,0 -> 0
output = [[0] * 14 for _ in range(16)]
for r in range(11, 14):
    for c in range(14):
        if grid[r][c] == 8:
            output[r][c] = 1
        # else 0

print("Option: just 8s become 1s in full grid:")
for row in output:
    print(' '.join([str(x) for x in row]))

# Maybe: 8s and 0s become 1s, 3s become 0s (globally)
output = [[0] * 14 for _ in range(16)]
for r in range(16):
    for c in range(14):
        if grid[r][c] in [8, 0]:
            output[r][c] = 1
        else:
            output[r][c] = 0

print("8+0 -> 1, 3 -> 0:")
for row in output:
    print(' '.join([str(x) for x in row]))

# What about: output is 16x14, but in the bbox region, 8->1 and 3->0?
# And 0 outside the bbox?
min_r, max_r = 11, 13
min_c, max_c = 1, 6

output = [[0] * 14 for _ in range(16)]
for r in range(16):
    for c in range(14):
        if min_r <= r <= max_r and min_c <= c <= max_c:
            if grid[r][c] == 8:
                output[r][c] = 1
            elif grid[r][c] == 3:
                output[r][c] = 0
            # 0 stays 0
        else:
            output[r][c] = 0  # already 0

print("Bbox with 8->1, 3->0, 0->0, rest 0:")
for row in output:
    print(' '.join([str(x) for x in row]))

# Maybe: in bbox, 3->0, 8->0, only 0->1?
